INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/5135,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/180301,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/1,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/4,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"应该用这个力量\n做什么呢……\n问问剑怎么说吧。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/5136,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/180301,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/1,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/5,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"即使变身了，\n我也还是我。\n就算能暂时变强，\n基础弱也是不行的。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
