INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/5138,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/180301,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/1,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/102,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/8,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"总有一天……\n要传达我的感情……\n一定！",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/5139,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/180301,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/1,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"要和什么人战斗吗？\n还是要修行？\n不管是哪种情况，\n我都陪你。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/5140,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/180301,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/2,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"持续变身的话\n会有多饿……\n我可不会尝试哦？",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/5141,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/180301,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/3,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"我并不想成为\n真正的公主，\n不过有个骑士在，\n还是很令人安心的。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/5142,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/180301,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/4,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"为了将来能用\n这股力量来救人……\n我希望有一天能在战斗\n之外的场合使用它。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/5143,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/180301,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/101,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/4,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"真希望你也感受到……\n你的力量流淌到我身上\n的那种感觉……还有，\n那个……我的心情……",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/5144,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/180301,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/102,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/8,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"坦白心意……\n竟然是那么困难的\n事情啊……但是，\n总有一天我要做到！",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
