INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6188,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/122001,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/1,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/2,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"父亲被一部分人评价为\n比海盗更像海盗。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6189,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/122001,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/1,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/3,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"为了防止武器\n被海风吹得生锈，\n好好保养一下吧。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6190,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/122001,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/1,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/4,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"如果是要寻宝的话，\n我想我能帮上忙。\n不过要看父亲有没有干劲了。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6191,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/122001,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/1,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/5,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"除灵很费神，\n因为一个弄不好的话，\n父亲也会成佛。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6192,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/122001,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/1,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/101,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/4,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"和那个人一起欣赏的\n海景……我想永远\n铭记在心。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6193,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/122001,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/1,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/102,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/8,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"即使变成幽灵，\n只要还能见上一面……\n我一定会对那个人……",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6194,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/122001,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/1,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"我的划船技术进步了，\n下次让你看看。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6195,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/122001,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/2,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"我要去采购，\n为航海做准备了。\n你有空吗？",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
