INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6809,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/124201,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/1,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"能不能帮忙装饰圣诞树？\n能装饰成什么样子，\n就靠少年的品味了哦。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6810,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/124201,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/2,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"派对的准备阶段也很开心。\n喂，少年，你能理解\n这种心情吗？",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6811,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/124201,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/3,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"你问为什么\n驯鹿的鼻子是红色的？\n因为驾驶没有灯的雪橇\n是会因违规而被取缔的。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
