INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6814,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/124201,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/102,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/8,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"喂，少年……\n你也该看习惯了吧。\n被你那么认真地盯着看，\n我会害羞的。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6815,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/124201,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/1,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/1,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"在朝阳的照耀下，\n街道上闪耀着\n银白色的光芒哦。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6816,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/124201,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/2,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/2,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"我们吃完午饭\n就出去走走吧，\n大家都在庆祝节日，\n街上的景色很美哦。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6817,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/124201,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/2,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/3,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/3,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"果然圣诞节的晚上\n才是重头戏呢。\n点上蜡烛，\n庄重地度过吧。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6819,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/124201,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/3,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/2,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"虽然穿着盔甲的时候\n和我无缘，但这松松软软的感觉\n真舒服啊……软软的……软软的……",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6820,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/124201,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/3,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/3,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"呵呵，好可爱呢。\n抱起来的时候，\n让我想起了那个\n在雪天出生的婴儿。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6821,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/124201,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/3,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/4,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"因为摘下了头盔，\n才能闻到这种香气……\n圣诞的魔法也不错呢。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
INSERT INTO `v1_c9931887bec97fb289068ada9e7bf037b812878740f23c13c8c699111474e332` VALUES (/*535bf49252c00f2e66a14821ad66e18e552a390a33171915663003b81f9cc806*/6822,/*efebac62f01ca916ec602ec249a088a7e98991b1a0e027956b8b665c757e199f*/124201,/*4baf257da523c2d813793875e58b5fba7e29a1875c943bf9bbba4d3795a2a5cd*/3,/*cf70bcfde13fac2adc9d9b3fc5db121eff6e7d74e118053e164eb0b37c7c9a18*/5,/*e7437054d529d4111bf4f01e6734e4736e0ebf41c3b4474806c0f1895933bd72*/1,/*0b53ecaaa212ea1122f76f334f7dc5496a2cca0a35542383b15be75999371cad*/0,/*2ac9897f8c39835e758041fc5e7169a6fab3657a5aff8be24287f0e93f7f0b51*/1,/*184a15194452513d77d485f656afb3231f235bdac46fd03269059fab2cd0978e*/"从指尖到内心深处\n都暖和起来了呢，\n只要有了它，就算是\n下雪的日子也能安心了。",/*bf778725e0ac4be4720577d0e5e9a8d14e9c05c8cf527c18733484eac6d29e30*/0);
